export interface ConnectorConfig {
  /** Shopify shared secret for HMAC-SHA256 verification (env: SHOPIFY_SHARED_SECRET) */
  shopifySharedSecret: string;
  /** Slack bot token with chat:write scope (env: SLACK_BOT_TOKEN) */
  slackBotToken: string;
  /** Slack channel ID to post messages to (env: SLACK_CHANNEL_ID) */
  slackChannelId: string;
  /** Optional fetch implementation for testing or custom environments */
  fetch?: typeof fetch;
}

export interface ShopifyOrderWebhookPayload {
  id: number;
  name: string;
  email: string;
  total_price: string;
  currency: string;
  line_items: Array<{
    title: string;
    quantity: number;
    price: string;
  }>;
}

export interface HandleResult {
  slackMessageTs: string;
  slackChannelId: string;
}

const REQUIRED_FIELDS: (keyof ShopifyOrderWebhookPayload)[] = [
  'id',
  'name',
  'email',
  'total_price',
  'currency',
  'line_items',
];

export async function handle(
  payload: ShopifyOrderWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  for (const field of REQUIRED_FIELDS) {
    const value = payload[field];
    if (value === undefined || value === null) {
      throw new Error(`Missing required field: ${field}`);
    }
  }

  if (!Array.isArray(payload.line_items) || payload.line_items.length === 0) {
    throw new Error('line_items must be a non-empty array');
  }

  const itemsSummary = payload.line_items
    .map((item) => `${item.quantity}x ${item.title}`)
    .join(', ');

  const text = `New order ${payload.name} from ${payload.email} for $${payload.total_price} ${payload.currency}\nItems: ${itemsSummary}`;

  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannelId,
      text,
    }),
  });

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`
    );
  }

  const data = (await response.json()) as { ok: boolean; channel: string; ts: string };
  if (!data.ok) {
    throw new Error(`Slack API returned error: ${JSON.stringify(data)}`);
  }

  return {
    slackMessageTs: data.ts,
    slackChannelId: data.channel,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, ShopifyOrderWebhookPayload } from './connector';
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
} from './fixtures';

const validConfig: ConnectorConfig = {
  shopifySharedSecret: 'test-shared-secret',
  slackBotToken: 'xoxb-test-token',
  slackChannelId: 'C1234567890',
};

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, {
      ...validConfig,
      fetch,
    });
    expect(calls.length).toBeGreaterThan(0);
    expect(result.slackMessageTs).toBe('1717000000.000200');
    expect(result.slackChannelId).toBe('C1234567890');
  });
});

describe('handle', () => {
  it('sends correctly formatted message with mapped fields', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ ok: true, channel: 'C1234567890', ts: '1717000000.000200' }, 200));
    await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, { ...validConfig, fetch });
    expect(calls[0].json).toEqual({
      channel: 'C1234567890',
      text: 'New order #1001 from customer@example.com for $129.95 USD\nItems: 2x T-Shirt, 1x Mug',
    });
  });

  it('uses Bearer token authentication', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ ok: true, channel: 'C1234567890', ts: '1' }, 200));
    await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, { ...validConfig, fetch });
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token');
  });

  it('throws when required field is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: true, channel: 'C1', ts: '1' }, 200));
    const payload = { ...SOURCE_EXAMPLE, email: undefined } as unknown as ShopifyOrderWebhookPayload;
    await expect(handle(payload, { ...validConfig, fetch })).rejects.toThrow('Missing required field: email');
  });

  it('throws when line_items is empty', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: true, channel: 'C1', ts: '1' }, 200));
    const payload = { ...SOURCE_EXAMPLE, line_items: [] } as unknown as ShopifyOrderWebhookPayload;
    await expect(handle(payload, { ...validConfig, fetch })).rejects.toThrow('line_items must be a non-empty array');
  });

  it('throws on non-2xx Slack response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401));
    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, { ...validConfig, fetch })).rejects.toThrow(
      'Slack API error: 401 Unauthorized at POST https://slack.com/api/chat.postMessage'
    );
  });

  it('throws when Slack returns ok: false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: false, error: 'channel_not_found' }, 200));
    await expect(handle(SOURCE_EXAMPLE as unknown as ShopifyOrderWebhookPayload, { ...validConfig, fetch })).rejects.toThrow(
      'Slack API returned error: {"ok":false,"error":"channel_not_found"}'
    );
  });
});

